        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = amzScreenNorm();
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luminance = dot(texColor.rgb, luminanceWeighting);
            float f = max(min((amzp_feathera/4.),abs(0.5-(1.-amzp_threshold))),0.00196);
            float t = (((1.-amzp_threshold)-0.5)*(1.003+f*2.))+0.5;
            float p = smoothstep(t-f, t+f, luminance);
            float3 rgb = float3(p,p,p);
            float4 trisolt = float4(rgb,texColor.a);
            float4 targetLuma = trisolt ;
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (amzp_lowThreshold*(1.0+amzp_featherb))-0.0001;
            float lowThresholdA = lowThresholdB-max(amzp_featherb,0.00001);
            float highThresholdA = (amzp_highThreshold*(1.0+amzp_featherb)-amzp_featherb)+0.0001;
            float highThresholdB = highThresholdA+max(amzp_featherb,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 antiblack = targetLuma * lumafx;
            float a = amzp_angle * 0.0174533;
            float2 st = amzLayerNorm();
            st -= 0.5;
            st -= (amzp_offset*float2(1,-1)) / 500.;
            st /= amzp_scale;
            st *= float2x2(sin(a), -cos(a), cos(a), sin(a));
            st += 0.5;
            float tx = length( st - 0.5 ) * 2.0;
            tx = clamp(tx,0.0,1.0);
            float4 color = mix(amzp_color1, amzp_color2, tx);
            antiblack = float4(antiblack.rgb*((amzp_gradColor>0.5)? color.rgb : amzp_color1.rgb), antiblack.a);
     amzOutput = mix(texColor, antiblack, amzp_alpha);
     }
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

